#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int x = 5, y = 10;
    printf("Before: x=%d, y=%d\n", x, y);
    swap(&x, &y);
    printf("After: x=%d, y=%d\n", x, y);
    return 0;
}

#include <stdio.h>

int main() {
    int scores[] = {85, 92, 78, 95, 88};
    int sum = 0;
    int n = sizeof(scores) / sizeof(scores[0]);

    for (int i = 0; i < n; i++) {
        sum += scores[i];
    }

    float avg = (float)sum / n;
    printf("Average score: %.2f\n", avg);
    return 0;
}

